/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// Extension class to access private method and variable for sales quantity forcontrols visibility - onhand list form
/// </summary>
using System.Reflection;
[ExtensionOf(ClassStr(PmfFormCtrl_InventOnHandItem))]
final class METPmfFormCtrl_InventOnHandItem_Extension
{
    public Set         detailsCWControlsloc,gridCWControlsloc,gridInventControlsloc;

}

Method.Source:
    /// <summary>
    /// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
    /// Visibiltity enabled if it is Sales quantity
    /// </summary>
    public void initPost()
    {
        next initPost();

        FormComboBoxControl  METPdsCWInventQuantityDisplay  = formRun.design().controlName('METPdsCWInventQuantityDisplay');

        if(METPdsCWInventQuantityDisplay.valueStr() == enum2Str(METPdsCWInventQuantityDisplay::Sales))
        {
            this.controlSalesQtyVisibility();
        }
    }

/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// Getting CW qty grid controls list
/// </summary>
public void gridCWControlsloc()
{
    var bindFlags = BindingFlags::Instance | BindingFlags::NonPublic;
    var field = this.GetType().GetField(identifierStr(gridCWControls), bindFlags);
   
    if (field)
    {
        gridCWControlsloc = field.GetValue(this); 
    }
}

/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// Getting Inventory qty grid controls list
/// </summary>
public void gridInventControlsloc()
{
    var bindFlags = BindingFlags::Instance | BindingFlags::NonPublic;
    var field = this.GetType().GetField(identifierStr(gridInventControls), bindFlags);
   
    if (field)
    {
        gridInventControlsloc = field.GetValue(this);
    }
}

  /// <summary>
  /// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
  /// To use toggleControlVisibility method - CW and Invent qty form controls
  /// </summary>
  /// <param name = "_controlSet"></param>
  public void modifyToggleControlVisibility(Set _controlSet)
  {
      System.Object[] parametersArray = new System.Object[2]();
      parametersArray.SetValue(_controlSet, 0);
      parametersArray.SetValue(false, 1);
       
      var bindFlags = BindingFlags::Instance | BindingFlags::NonPublic;

      var methodInfo = this.GetType().GetMethod(methodStr(PmfFormCtrl_InventOnHandItem, toggleControlVisibility), bindFlags);

      if (methodInfo)
      {
         methodInfo.Invoke(this,  parametersArray);
      }
  }

/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// Calling CW and Invent qty form controls, visibility methods.
/// </summary>
void controlSalesQtyVisibility()
{
    this.gridCWControlsloc();
    this.gridInventControlsloc();
    this.modifyToggleControlVisibility(gridCWControlsloc);
    this.modifyToggleControlVisibility(gridInventControlsloc);
}
